#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock rationale: read event JSON from GITHUB_EVENT_PATH (provided by GitHub Actions)\nevent_path="${GITHUB_EVENT_PATH:-}"\nif [[ -z "$event_path" || ! -f "$event_path" ]]; then\n  echo "No event file found, exiting."\n  exit 0\nfi\n\n# Extract PR title using jq (available on default runners)\ntitle=$(jq -r .pull_request.title "$event_path")\nlabels=()\n\n# Simple keyword‑to‑label mapping\nif [[ "$title" =~ [Bb]ug ]]; then\n  labels+=("bug")\nfi\nif [[ "$title" =~ [Ff]eature ]]; then\n  labels+=("enhancement")\nfi\nif [[ "$title" =~ [Dd]oc|[Dd]ocumentation ]]; then\n  labels+=("documentation")\nfi\n\nif (( ${#labels[@]} )); then\n  joined=$(IFS=,; echo "${labels[*]}")\n  echo "::add-labels::$joined"\nfi
